// spec: specs/delivery.md §11 · кейс .qa/tests/delivery/dlv-15-delivery-note-barcode.md
// seed: tests/seed.admin.spec.ts
// #f43d23 (בקשת לקוח, עבר QA 28.10): штрихкод в каждой строке товара תעודת משלוח — экран и печать/PDF.
// Обновлено 28.10 под #b4cd60 (עבר QA 28.10): режим таблицы зависит от ШИРИНЫ САМОЙ ТАБЛИЦЫ (container query 36rem = 576px),
//   а не окна. Таблица ≥576 — 5 колонок, 1 видимый штрихкод в колонке «מק"ט» (cellIndex 1); <576 — ряды (3 колонки),
//   1 штрихкод под именем (cellIndex 0). Напр. 1280 с меню — таблица 501 → ряды; 1354/1355 с меню — 575/576; 1024 с меню — 585.
//   Без прокрутки вбок. Печать (emulateMedia print + page.pdf A4): 1 штрихкод на строку; длинный не-EAN מק"ט (≥13 символов) —
//   отдельной строкой tr.pd-barcode-row (colspan=5) сразу под товаром; tbody.pd-line break-inside: avoid; нет «סטטוס»/«סופק ב».
//   מק"ט на иврите / кириллице / пустой — без штрихкода, без ошибок консоли.
// Данные — существующие заказы, только чтение: #504 (EAN-13 + Code128 «12245»), #616 (QAFD2F503115, 12 симв.),
//   #554 (QA-AUTO-AEF1-…, 21 симв.), #663 (נדחתה; 10×21 симв., MAX40, иврит, кириллица). Ничего не сохраняется → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const NOTES = {
  504: '6f797bf5-1ef8-44eb-8ad5-073e0b0f341e',
  616: '30041824-b71b-4b55-9c26-74dda4f67cd4',
  554: 'ca6534d2-3605-4a95-9080-7af08b98ba3d',
  663: 'f7287a79-a4a9-45dc-a0f0-6f90ca7c8da6',
} as const;
type No = keyof typeof NOTES;

async function openNote(page: Page, no: No) {
  await page.goto(`/delivery/${NOTES[no]}`);
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('svg[data-barcode]').first()).toBeAttached({ timeout: 20_000 });
}

/** Экранная таблица товаров: по строке — מק"ט, сколько штрихкодов видно и в какой ячейке. */
const screenRows = (page: Page) => page.evaluate(() => {
  const t = [...document.querySelectorAll('table')].find((x) => !x.classList.contains('pd-table') && x.checkVisibility())!;
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, tw: t.getBoundingClientRect().width,
    cols: [...t.tHead!.rows[0].cells].filter((c) => c.checkVisibility()).length,
    rows: [...t.tBodies[0].rows].map((r) => {
      const sku = (r.querySelector('bdi')?.textContent ?? '').trim();
      const vis = [...r.querySelectorAll('svg[data-barcode]')].filter((s) => s.checkVisibility() && s.getBoundingClientRect().width > 0);
      return { name: (r.cells[0].firstChild?.textContent ?? '').trim(), sku, visible: vis.length, cells: vis.map((s) => (s.closest('td') as HTMLTableCellElement).cellIndex), labels: vis.map((s) => s.getAttribute('aria-label')) };
    }),
  };
});

/** Печатная таблица (pd-table) при emulateMedia print. */
const printRows = (page: Page) => page.evaluate(() => {
  const t = document.querySelector('table.pd-table') as HTMLTableElement;
  return {
    visible: t.checkVisibility(),
    lines: [...t.querySelectorAll('tbody.pd-line')].map((b) => {
      const first = b.rows[0];
      const sku = (first.cells[1].firstChild?.textContent ?? '').trim();
      const svgs = [...b.querySelectorAll('svg[data-barcode]')].filter((s) => s.checkVisibility());
      const bcRow = b.querySelector('tr.pd-barcode-row') as HTMLTableRowElement | null;
      return {
        name: first.cells[0].textContent!.trim(), sku, svgs: svgs.length, labels: svgs.map((s) => s.getAttribute('aria-label')),
        inSkuCell: first.cells[1].querySelectorAll('svg[data-barcode]').length,
        bcRow: bcRow ? { index: bcRow.sectionRowIndex, colspan: bcRow.cells[0].colSpan, cells: bcRow.cells.length, svg: bcRow.querySelectorAll('svg[data-barcode]').length } : null,
        breakInside: getComputedStyle(b).breakInside,
      };
    }),
  };
});

/** 8/12/13 цифр с неверной контрольной цифрой — без штрихкода (#1ee7e8). */
const badCheckDigit = (sku: string) => {
  if (!/^(\d{8}|\d{12}|\d{13})$/.test(sku)) return false;
  let n = 0;
  for (let i = sku.length - 2, w = 3; i >= 0; i--, w = 4 - w) n += Number(sku[i]) * w;
  return (10 - (n % 10)) % 10 !== Number(sku[sku.length - 1]);
};
const encodable = (sku: string) => sku !== '' && /^[\x20-\x7E]+$/.test(sku) && !badCheckDigit(sku);
const isEan13 = (sku: string) => /^\d{13}$/.test(sku);

/** Ожидаемая ячейка штрихкода по ширине таблицы (#b4cd60): ≥576 — колонка «מק"ט» (5 колонок), <576 — под именем (ряды, 3 колонки). */
function cellByTable(m: Awaited<ReturnType<typeof screenRows>>, tag: string): 0 | 1 {
  const wide = m.tw >= 576;
  expect(m.cols, `${tag}: таблица ${Math.round(m.tw)}px — ${wide ? '5 колонок' : 'ряды, 3 колонки'}`).toBe(wide ? 5 : 3);
  return wide ? 1 : 0;
}

/** Меню сбоку раскрыто (новое окно — раскрыто по умолчанию; на всякий случай). */
async function sidebarOpen(page: Page) {
  const expand = page.getByRole('button', { name: 'הרחבת תפריט הצד' });
  if (await expand.isVisible()) await expand.click();
}

function expectScreen(m: Awaited<ReturnType<typeof screenRows>>, cell: 0 | 1, tag: string) {
  expect(m.rows.length, `${tag}: есть строки`).toBeGreaterThan(0);
  for (const r of m.rows) {
    if (encodable(r.sku)) {
      expect(r.visible, `${tag}: «${r.name}» (${r.sku}) — ровно 1 видимый штрихкод`).toBe(1);
      expect(r.cells[0], `${tag}: «${r.name}» — штрихкод в ${cell === 1 ? 'колонке «מק\"ט»' : 'ячейке имени'}`).toBe(cell);
      expect(r.labels[0], `${tag}: «${r.name}» — штрихкод по מק"ט`).toBe(`ברקוד ${r.sku}`);
    } else {
      expect(r.visible, `${tag}: «${r.name}» (מק"ט «${r.sku}») — без штрихкода`).toBe(0);
    }
  }
}

function watchErrors(page: Page) {
  const errors: string[] = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(e.message));
  return errors;
}

test.describe('delivery — ברקוד בכל שורת מוצר בתעודת משלוח (#f43d23)', () => {
  test('1 ברקוד גלוי בכל שורה: טבלה ≥576px — בעמודת «מק"ט», <576px — מתחת לשם (1440/1355/1354/1280/1024/640/639 עם תפריט) בלי גלילה לרוחב #f43d23 #b4cd60 @desktop @delivery @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    for (const no of [504, 616, 554] as No[]) {
      await page.setViewportSize({ width: 1440, height: 900 });
      await openNote(page, no);
      await sidebarOpen(page);
      for (const w of [1440, 1355, 1354, 1280, 1024, 640, 639]) {
        await page.setViewportSize({ width: w, height: 900 });
        await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
        const m = await screenRows(page);
        const tag = `#${no} ${w} (таблица ${Math.round(m.tw)})`;
        expectScreen(m, cellByTable(m, tag), tag);
        expect(m.docSW, `${tag}: без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
      }
    }
  });

  test('390: ברקוד אחד מתחת לשם בכל שורה, בלי גלילה לרוחב #f43d23 @iphone @delivery @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    for (const no of [504, 554, 663] as No[]) {
      await openNote(page, no);
      const m = await screenRows(page);
      expect(m.tw, `#${no} ${m.vw}: таблица уже 576 — ряды`).toBeLessThan(576);
      expectScreen(m, 0, `#${no} ${m.vw}`);
      expect(m.docSW, `#${no}: без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
    }
  });

  test('הדפסה: ברקוד אחד לשורה; מק"ט ארוך (≥13, לא EAN) — שורה נפרדת tr.pd-barcode-row colspan=5 מתחת למוצר; break-inside: avoid; בלי «סטטוס»/«סופק ב»; PDF A4 #f43d23 @desktop @delivery @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    for (const no of [504, 616, 554, 663] as No[]) {
      await page.emulateMedia({ media: 'screen' });
      await openNote(page, no);
      await page.emulateMedia({ media: 'print' });
      const p = await printRows(page);
      expect(p.visible, `#${no}: печатная таблица видна в print`).toBe(true);
      expect(p.lines.length, `#${no}: строки товаров`).toBeGreaterThan(0);
      for (const l of p.lines) {
        const tag = `#${no} печать «${l.name}» (${l.sku})`;
        expect(l.breakInside, `${tag}: tbody.pd-line break-inside`).toBe('avoid');
        if (!encodable(l.sku)) {
          expect(l.svgs, `${tag}: без штрихкода`).toBe(0);
          expect(l.bcRow, `${tag}: без строки-штрихкода`).toBeNull();
          continue;
        }
        expect(l.svgs, `${tag}: ровно 1 штрихкод`).toBe(1);
        expect(l.labels[0], `${tag}: штрихкод по מק"ט`).toBe(`ברקוד ${l.sku}`);
        if (l.sku.length >= 13 && !isEan13(l.sku)) {
          expect(l.bcRow, `${tag}: длинный — отдельная строка tr.pd-barcode-row`).not.toBeNull();
          expect(l.bcRow, `${tag}: строка сразу под товаром, одна ячейка colspan=5`).toEqual({ index: 1, colspan: 5, cells: 1, svg: 1 });
          expect(l.inSkuCell, `${tag}: в колонке «מק"ט» штрихкода нет`).toBe(0);
        } else {
          expect(l.bcRow, `${tag}: короткий/EAN — без отдельной строки`).toBeNull();
          expect(l.inSkuCell, `${tag}: штрихкод в колонке «מק"ט»`).toBe(1);
        }
      }
      const printed = await page.evaluate(() => document.body.innerText);
      expect(printed, `#${no}: в печати нет «סטטוס»`).not.toMatch(/סטטוס/);
      expect(printed, `#${no}: в печати нет «סופק ב»`).not.toMatch(/סופקה? ב/);
      const pdf = await page.pdf({ format: 'A4', printBackground: true });
      expect(pdf.subarray(0, 5).toString(), `#${no}: PDF A4 сформирован`).toBe('%PDF-');
    }
    await page.emulateMedia({ media: 'screen' });
  });

  test('#663: מק"ט בעברית / בקירילית — השורה בלי ברקוד, במסך ובהדפסה, בלי שגיאות בקונסול #f43d23 @desktop @delivery @prod-safe', async ({ page }) => {
    const errors = watchErrors(page);
    await openNote(page, 663);
    const m = await screenRows(page);
    const odd = m.rows.filter((r) => /[֐-׿Ѐ-ӿ]/.test(r.sku));
    expect(odd.map((r) => r.sku), 'есть строки с ивритом и кириллицей в מק"ט').toEqual(expect.arrayContaining([expect.stringMatching(/[֐-׿]/), expect.stringMatching(/[Ѐ-ӿ]/)]));
    for (const r of odd) expect(r.visible, `«${r.name}» (${r.sku}) — без штрихкода на экране`).toBe(0);
    const empty = m.rows.filter((r) => r.sku === '');
    for (const r of empty) expect(r.visible, `«${r.name}» без מק"ט — без штрихкода`).toBe(0);
    await page.emulateMedia({ media: 'print' });
    const p = await printRows(page);
    for (const l of p.lines.filter((x) => !encodable(x.sku))) expect(l.svgs, `печать «${l.name}» (${l.sku}) — без штрихкода`).toBe(0);
    await page.emulateMedia({ media: 'screen' });
    expect(errors, 'нет ошибок в консоли').toEqual([]);
  });
});
